 * 轨交票务清分 API。
 */
@RestController
@RequestMapping("/api/metro")
public class MetroController {

    private final MetroService metroService;

    public MetroController(MetroService metroService) {
        this.metroService = metroService;
    }

    /** 进闸。 */
    @PostMapping("/entry")
