package com.example.starter.metro.dto;

/**
 * 可幂等重放的响应：重放时返回首份结果并标记 replayed。
 *
 * @param <T> 响应类型
 */
public interface ReplayableResponse<T> {

    /**
     * 返回标记为重放的副本。
     */
    T asReplayed();
}

package com.example.starter.metro.dto;

import java.util.List;

/**
 * 批次视图：批次状态、合计与可逐笔复算的清分明细、对账差异。
 *
 * @param bizDate       业务日期
 * @param status        批次状态（OPEN/SEALED）
 * @param totalCents    批次合计（分）；未封账时为明细实时合计
 * @param txnCount      批次内交易笔数
 * @param details       清分明细（含暂记、冲销、实结）
 * @param discrepancies 对账差异登记
 */
public record BatchViewResponse(String bizDate, String status, long totalCents, int txnCount,
                                List<DetailView> details, List<DiscrepancyView> discrepancies) {

    /**
     * 清分明细视图。
     */
    public record DetailView(String txnNo, String lineCode, long distanceM, String ratio,
                             long amountCents, String entryType) {
    }

    /**
     * 对账差异视图。
     */
    public record DiscrepancyView(String txnNo, long amountCents, String reason) {
    }
}

package com.example.starter.metro.dto;

/**
 * 出闸/补登响应。
 *
 * @param txnNo           交易流水号
 * @param status          交易状态（COMPLETED）
 * @param distanceM       计费里程（米）
 * @param fareCents       实收金额（分）
 * @param penaltyCents    超时补收（分）
 * @param transfer        是否换乘接续
 * @param compensated     是否补登（冲销暂记后按实结算）
 * @param bizDate         入账业务日期
 * @param lateDiscrepancy 是否因批次已封账而登记对账差异
 * @param replayed        是否幂等重放命中首次结果
 */
public record ExitResponse(String txnNo, String status, long distanceM, long fareCents,
                           long penaltyCents, boolean transfer, boolean compensated,
                           String bizDate, boolean lateDiscrepancy, boolean replayed)
        implements ReplayableResponse<ExitResponse> {

    @Override
    public ExitResponse asReplayed() {
        return new ExitResponse(txnNo, status, distanceM, fareCents, penaltyCents, transfer,
                compensated, bizDate, lateDiscrepancy, true);
    }
}

