/** 按票卡号查询。 */
public Optional<CardRow> findCardById(String cardId) {
    List<CardRow> rows = jdbcTemplate.query(
            "SELECT card_id, status, version, close_request_id, closed_at FROM metro_card"
            + " WHERE card_id = ?",
            CARD_MAPPER, cardId);
    return rows.stream().findFirst();
}

/** 按票卡号查询并加行锁。 */
public Optional<CardRow> findCardByIdForUpdate(String cardId) {
    List<CardRow> rows = jdbcTemplate.query(
            "SELECT card_id, status, version, close_request_id, closed_at FROM metro_card"
            + " WHERE card_id = ? FOR UPDATE",
            CARD_MAPPER, cardId);
    return rows.stream().findFirst();
}

/** 关闭票卡并使版本加 1。 */
public void closeCard(String cardId, String closeRequestId, LocalDateTime closedAt) {
    jdbcTemplate.update(
            "UPDATE metro_card SET status = 'CLOSED', version = version + 1, close_request_id = ?,"
            + " closed_at = ?, updated_at = ? WHERE card_id = ?",
            closeRequestId, Timestamp.valueOf(closedAt), Timestamp.valueOf(LocalDateTime.now()), cardId);
}

// ============================ 退款单 ============================

private static final RowMapper<RefundRow> REFUND_MAPPER = (rs, rowNum) -> new RefundRow(
        rs.getLong("id"),
        rs.getString("refund_no"),
        rs.getString("txn_no"),
        rs.getLong("amount_cents"),
        rs.getString("status"),
        rs.getInt("version"),
        rs.getString("reviewer_one"),
        rs.getString("reviewer_two"),
        rs.getString("apply_request_id"),
        rs.getString("confirm_request_id"),
        toLong(rs, "adjustment_batch_id"),
        toDateTime(rs, "confirmed_at"));

/** 插入退款单（PENDING，版本 1）；退款单号重复抛 DuplicateKeyException。 */
public void insertRefund(RefundRow row) {
    LocalDateTime now = LocalDateTime.now();
    jdbcTemplate.update(
            "INSERT INTO refund_order (refund_no, txn_no, amount_cents, status, version,"
            + " apply_request_id, created_at) VALUES (?, ?, ?, 'PENDING', 1, ?, ?)",
            row.refundNo(), row.txnNo(), row.amountCents(), row.applyRequestId(),
            Timestamp.valueOf(now));
}

/** 按退款单号查询。 */
public Optional<RefundRow> findRefundByNo(String refundNo) {
    List<RefundRow> rows = jdbcTemplate.query(
            "SELECT id, refund_no, txn_no, amount_cents, status, version, reviewer_one, reviewer_two,"
            + " apply_request_id, confirm_request_id, adjustment_batch_id, confirmed_at"
            + " FROM refund_order WHERE refund_no = ?",
            REFUND_MAPPER, refundNo);
    return rows.stream().findFirst();
}

/** 按退款单号查询并加行锁。 */
public Optional<RefundRow> findRefundByNoForUpdate(String refundNo) {
    List<RefundRow> rows = jdbcTemplate.query(
            "SELECT id, refund_no, txn_no, amount_cents, status, version, reviewer_one, reviewer_two,"
            + " apply_request_id, confirm_request_id, adjustment_batch_id, confirmed_at"
            + " FROM refund_order WHERE refund_no = ? FOR UPDATE",
            REFUND_MAPPER, refundNo);
    return rows.stream().findFirst();
}

/** 双人确认生效：置 CONFIRMED、登记两名复核人与幂等键，版本加 1。 */
public void confirmRefund(long id, String reviewerOne, String reviewerTwo,
                         String confirmRequestId, LocalDateTime confirmedAt) {
    jdbcTemplate.update(
            "UPDATE refund_order SET status = 'CONFIRMED', version = version + 1, reviewer_one = ?,"
            + " reviewer_two = ?, confirm_request_id = ?, confirmed_at = ? WHERE id = ?",
            reviewerOne, reviewerTwo, confirmRequestId, Timestamp.valueOf(confirmedAt), id);
}

/** 将退款单挂到调账批次（纳入一次后不得改挂）。 */
public void attachRefundBatch(long refundId, long adjustmentBatchId) {
    jdbcTemplate.update(
            "UPDATE refund_order SET adjustment_batch_id = ? WHERE id = ? AND adjustment_batch_id IS NULL",
            adjustmentBatchId, refundId);
}

// ============================ 负向调整明细 ============================

private static final RowMapper<AdjustmentDetailRow> ADJUSTMENT_DETAIL_MAPPER = (rs, rowNum) ->
        new AdjustmentDetailRow(
                rs.getLong("id"),
                rs.getString("refund_no"),
                rs.getString("txn_no"),
                rs.getString("line_code"),
                rs.getBigDecimal("ratio").toPlainString(),
                rs.getLong("amount_cents"));

/** 插入负向调整明细（金额恒为负）。 */
public void insertAdjustmentDetail(AdjustmentDetailRow row) {
    jdbcTemplate.update(
            "INSERT INTO adjustment_detail (refund_no, txn_no, line_code, ratio, amount_cents, created_at)"
            + " VALUES (?,?,?,?,?,?)",
            row.refundNo(), row.txnNo(), row.lineCode(), new java.math.BigDecimal(row.ratio()),
            row.amountCents(), Timestamp.valueOf(LocalDateTime.now()));
}

/** 查询退款单的全部负向调整明细。 */
public List<AdjustmentDetailRow> findAdjustmentDetailsByRefund(String refundNo) {
    return jdbcTemplate.query(
            "SELECT id, refund_no, txn_no, line_code, ratio, amount_cents FROM adjustment_detail"
            + " WHERE refund_no = ? ORDER BY id",
            ADJUSTMENT_DETAIL_MAPPER, refundNo);
}

/** 统计退款单负向调整合计（分，负数）。 */
public long sumAdjustmentDetailsByRefund(String refundNo) {
    Long sum = jdbcTemplate.queryForObject(
            "SELECT COALESCE(SUM(amount_cents), 0) FROM adjustment_detail WHERE refund_no = ?",
            Long.class, refundNo);
    return sum == null ? 0L : sum;
}

/**
 * 按线路统计行程累计已调整金额（分，负数），用于并发确认时占用可退余额。
 */
public List<LineAmountRow> sumAdjustedByLineForTxn(String txnNo) {
    return jdbcTemplate.query(
            "SELECT line_code, SUM(amount_cents) AS amount FROM adjustment_detail"
            + " WHERE txn_no = ? GROUP BY line_code",
            (rs, rowNum) -> new LineAmountRow(rs.getString("line_code"), rs.getLong("amount")),
            txnNo);
}

/** 查询行程按实结算的正向清分明细（NORMAL/SETTLE），作为原线路实收份额。 */
public List<DetailRow> findSettlementDetailsByTxn(String txnNo) {
    return jdbcTemplate.query(
            "SELECT id, batch_id, txn_no, line_code, distance_m, ratio, amount_cents, entry_type"
            + " FROM clearing_detail WHERE txn_no = ? AND entry_type IN ('NORMAL','SETTLE')"
            + " AND amount_cents > 0 ORDER BY id",
            DETAIL_MAPPER, txnNo);
}

// ============================ 调账批次 ============================

private static final RowMapper<AdjustmentBatchRow> ADJUSTMENT_BATCH_MAPPER = (rs, rowNum) ->
        new AdjustmentBatchRow(
                rs.getLong("id"),
                rs.getString("batch_no"),
                rs.getString("status"),
                rs.getLong("total_cents"),
                rs.getInt("order_count"),
                rs.getInt("version"),
                rs.getString("seal_request_id"),
                toDateTime(rs, "sealed_at"));

private static final String ADJ_BATCH_COLUMNS =
        "id, batch_no, status, total_cents, order_count, version, seal_request_id, sealed_at";

/** 开立开放调账批次；已存在开放批次时唯一索引冲突抛 DuplicateKeyException。 */
public long insertAdjustmentBatch(String batchNo) {
    KeyHolder keyHolder = new GeneratedKeyHolder();
    LocalDateTime now = LocalDateTime.now();
    jdbcTemplate.update(connection -> {
        var ps = connection.prepareStatement(
                "INSERT INTO adjustment_batch (batch_no, status, total_cents, order_count, version,"
                + " open_flag, created_at) VALUES (?, 'OPEN', 0, 0, 1, 'O', ?)",
                Statement.RETURN_GENERATED_KEYS);
        ps.setString(1, batchNo);
        ps.setTimestamp(2, Timestamp.valueOf(now));
        return ps;
    }, keyHolder);
    return keyHolder.getKey().longValue();
}

/** 查询唯一开放调账批次。 */
public Optional<AdjustmentBatchRow> findOpenAdjustmentBatch() {
    List<AdjustmentBatchRow> rows = jdbcTemplate.query(
            "SELECT " + ADJ_BATCH_COLUMNS + " FROM adjustment_batch WHERE open_flag = 'O'",
            ADJUSTMENT_BATCH_MAPPER);
    return rows.stream().findFirst();
}

/** 查询唯一开放调账批次并加行锁。 */
public Optional<AdjustmentBatchRow> findOpenAdjustmentBatchForUpdate() {
    List<AdjustmentBatchRow> rows = jdbcTemplate.query(
            "SELECT " + ADJ_BATCH_COLUMNS + " FROM adjustment_batch WHERE open_flag = 'O' FOR UPDATE",
            ADJUSTMENT_BATCH_MAPPER);
    return rows.stream().findFirst();
}

/** 按业务编号查询调账批次。 */
public Optional<AdjustmentBatchRow> findAdjustmentBatchByNo(String batchNo) {
    List<AdjustmentBatchRow> rows = jdbcTemplate.query(
            "SELECT " + ADJ_BATCH_COLUMNS + " FROM adjustment_batch WHERE batch_no = ?",
            ADJUSTMENT_BATCH_MAPPER, batchNo);
    return rows.stream().findFirst();
}

/** 按业务编号查询调账批次并加行锁。 */
public Optional<AdjustmentBatchRow> findAdjustmentBatchByNoForUpdate(String batchNo) {
    List<AdjustmentBatchRow> rows = jdbcTemplate.query(
            "SELECT " + ADJ_BATCH_COLUMNS + " FROM adjustment_batch WHERE batch_no = ? FOR UPDATE",
            ADJUSTMENT_BATCH_MAPPER, batchNo);
    return rows.stream().findFirst();
}

/** 按主键查询调账批次。 */
public Optional<AdjustmentBatchRow> findAdjustmentBatchById(long id) {
    List<AdjustmentBatchRow> rows = jdbcTemplate.query(
            "SELECT " + ADJ_BATCH_COLUMNS + " FROM adjustment_batch WHERE id = ?",
            ADJUSTMENT_BATCH_MAPPER, id);
    return rows.stream().findFirst();
}

/** 纳入一笔调整单：累加负向合计与笔数，版本加 1。 */
public void addAdjustmentToBatch(long batchId, long deltaCents) {
    jdbcTemplate.update(
            "UPDATE adjustment_batch SET total_cents = total_cents + ?, order_count = order_count + 1,"
            + " version = version + 1 WHERE id = ? AND status = 'OPEN'",
            deltaCents, batchId);
}

/** 封存调账批次：重算合计与笔数快照、释放开放唯一标记，版本加 1。 */
public void sealAdjustmentBatch(long batchId, long totalCents, int orderCount,
                                String sealRequestId, LocalDateTime sealedAt) {
    jdbcTemplate.update(
            "UPDATE adjustment_batch SET status = 'SEALED', total_cents = ?, order_count = ?,"
            + " version = version + 1, open_flag = NULL, seal_request_id = ?, sealed_at = ?"
            + " WHERE id = ?",
            totalCents, orderCount, sealRequestId, Timestamp.valueOf(sealedAt), batchId);
}

/** 按批次重算负向调整合计与不重复退款单笔数。 */
public BatchTotalRow recalcAdjustmentBatchTotal(long batchId) {
    return jdbcTemplate.queryForObject(
            "SELECT COALESCE(SUM(d.amount_cents), 0) AS total_cents,"
            + " COUNT(DISTINCT d.refund_no) AS order_count FROM adjustment_detail d"
            + " JOIN refund_order r ON r.refund_no = d.refund_no"
            + " WHERE r.adjustment_batch_id = ?",
            (rs, rowNum) -> new BatchTotalRow(rs.getLong("total_cents"), rs.getInt("order_count")),
            batchId);
}

/**
 * 交易流水行。
 */
public record TxnRow(Long id, String txnNo, String cardId, String entryStation,
                     LocalDateTime entryTime, String exitStation, LocalDateTime exitTime,
                     String status, Long distanceM, long chainBaseM, Long fareCents,
                     long penaltyCents, boolean transfer, boolean estimated,
                     Long batchId, LocalDate bizDate, String requestId, String fingerprint) {
}

