package com.example.starter.metro;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.time.LocalDateTime;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.TreeSet;
import java.util.function.Supplier;

import com.example.starter.metro.MetroRepository.AdjustmentBatchRow;
import com.example.starter.metro.MetroRepository.AdjustmentDetailRow;
import com.example.starter.metro.MetroRepository.BatchRow;
import com.example.starter.metro.MetroRepository.CardRow;
import com.example.starter.metro.MetroRepository.DetailRow;
import com.example.starter.metro.MetroRepository.IdemRow;
import com.example.starter.metro.MetroRepository.LineAmountRow;
import com.example.starter.metro.MetroRepository.RefundRow;
import com.example.starter.metro.MetroRepository.TxnRow;
import com.example.starter.metro.dto.AdjustmentIncludeRequest;
import com.example.starter.metro.dto.AdjustmentIncludeResponse;
import com.example.starter.metro.dto.AdjustmentSealRequest;
import com.example.starter.metro.dto.AdjustmentSealResponse;
import com.example.starter.metro.dto.CardCloseRequest;
import com.example.starter.metro.dto.CardCloseResponse;
import com.example.starter.metro.dto.LineBalanceResponse;
import com.example.starter.metro.dto.RefundApplyRequest;
import com.example.starter.metro.dto.RefundApplyResponse;
import com.example.starter.metro.dto.RefundConfirmRequest;
import com.example.starter.metro.dto.RefundConfirmResponse;
import com.example.starter.metro.dto.RefundViewResponse;
import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.dao.DuplicateKeyException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;

/**
 * 封账行程退款冲正服务。
 *
 * <p>退款只能引用已封账且已按实结算的行程；确认成功时在同一事务内由两名不同复核人
 * 共同校验、按原线路实收份额分摊占用可退余额，并生成独立负向调整明细。原交易流水与
 * 原封账合计只读，永不回写。</p>
 *
 * <p>所有写操作携带 expectedVersion（版本从 1 开始，成功变更加 1）与 requestId；
 * 指纹结构化覆盖版本、集合与精确时刻，业务变更与幂等结果在同一事务提交。</p>
 */
@Service
public class RefundService {

    static final String SCOPE_APPLY = "REFUND_APPLY";
    static final String SCOPE_CONFIRM = "REFUND_CONFIRM";
    static final String SCOPE_INCLUDE = "ADJ_INCLUDE";
    static final String SCOPE_SEAL_BATCH = "ADJ_SEAL";
    static final String SCOPE_CARD_CLOSE = "CARD_CLOSE";

    private final MetroRepository repository;
    private final TransactionTemplate txTemplate;
    private final ObjectMapper objectMapper;

    public RefundService(MetroRepository repository, PlatformTransactionManager transactionManager,
                         ObjectMapper objectMapper) {
        this.repository = repository;
        this.txTemplate = new TransactionTemplate(transactionManager);
        this.objectMapper = objectMapper;
    }

    /** 退款申请：行程须已封账且按实结算，累计退款不得超过原实收。 */
    public RefundApplyResponse apply(RefundApplyRequest request) {
        String fingerprint = fingerprint(List.of(
                SCOPE_APPLY, request.requestId(), request.refundNo(), request.txnNo(),
                request.amountCents(), request.applyTime().toString()));
        return idempotent(SCOPE_APPLY, request.requestId(), fingerprint, RefundApplyResponse.class,
                () -> doApply(request), () -> {
                    Optional<RefundRow> sameNo = repository.findRefundByNo(request.refundNo());
                    if (sameNo.isPresent()) {
                        throw MetroException.conflict("DUPLICATE_REFUND_NO", "退款单号重复: " + request.refundNo());
                    }
                    throw MetroException.conflict("IDEMPOTENCY_RACE", "幂等键并发冲突");
                });
    }

    /** 双人确认：同一事务共同校验，分摊并占用可退余额，生成负向调整明细。 */
    public RefundConfirmResponse confirm(RefundConfirmRequest request) {
        List<String> reviewers = new ArrayList<>(new TreeSet<>(request.reviewers()));
        String fingerprint = fingerprint(List.of(
                SCOPE_CONFIRM, request.requestId(), request.refundNo(), request.expectedVersion(),
                reviewers, request.confirmTime().toString()));
        return idempotent(SCOPE_CONFIRM, request.requestId(), fingerprint, RefundConfirmResponse.class,
                () -> doConfirm(request, reviewers),
                () -> {
                    Optional<RefundRow> sameNo = repository.findRefundByNo(request.refundNo());
                    if (sameNo.isPresent() && SCOPE_CONFIRM.equals(request.requestId()) == false
                            && request.requestId().equals(sameNo.get().confirmRequestId())) {
                        throw MetroException.conflict("IDEMPOTENCY_RACE", "幂等键并发冲突");
                    }
                    throw MetroException.conflict("IDEMPOTENCY_RACE", "幂等键并发冲突");
                });
    }

    /** 将已确认退款调整单纳入唯一开放调账批次；重复纳入不重复计额。 */
    public AdjustmentIncludeResponse include(AdjustmentIncludeRequest request) {
        String fingerprint = fingerprint(List.of(
                SCOPE_INCLUDE, request.requestId(), request.refundNo(), request.expectedVersion(),
                request.includeTime().toString()));
        return idempotent(SCOPE_INCLUDE, request.requestId(), fingerprint,
                AdjustmentIncludeResponse.class, () -> doInclude(request),
                () -> { throw MetroException.conflict("IDEMPOTENCY_RACE", "幂等键并发冲突"); });
    }

    /** 封存调账批次；封存后只读，重复封存幂等成功。 */
    public AdjustmentSealResponse sealBatch(AdjustmentSealRequest request) {
        String fingerprint = fingerprint(List.of(
                SCOPE_SEAL_BATCH, request.requestId(), request.batchNo(), request.expectedVersion(),
                request.sealTime().toString()));
        return idempotent(SCOPE_SEAL_BATCH, request.requestId(), fingerprint,
                AdjustmentSealResponse.class, () -> doSealBatch(request),
                () -> { throw MetroException.conflict("IDEMPOTENCY_RACE", "幂等键并发冲突"); });
    }

    /** 关闭票卡；已成功退款的历史重放不受影响。 */
    public CardCloseResponse closeCard(CardCloseRequest request) {
        String fingerprint = fingerprint(List.of(
                SCOPE_CARD_CLOSE, request.requestId(), request.cardId(), request.expectedVersion(),
                request.closeTime().toString()));
        return idempotent(SCOPE_CARD_CLOSE, request.requestId(), fingerprint, CardCloseResponse.class,
                () -> doCloseCard(request),
                () -> { throw MetroException.conflict("IDEMPOTENCY_RACE", "幂等键并发冲突"); });
    }

    /** 查询行程逐线路原实收份额、已退与可退余额。 */
    public LineBalanceResponse lineBalances(String txnNo) {
        TxnRow txn = repository.findTxnByNo(txnNo)
                .orElseThrow(() -> MetroException.notFound("TXN_NOT_FOUND", "交易流水不存在: " + txnNo));
        boolean settled = "COMPLETED".equals(txn.status());
        BatchRow batch = txn.batchId() == null ? null
                : repository.findBatchById(txn.batchId()).orElse(null);
        boolean sealed = batch != null && "SEALED".equals(batch.status());

        List<DetailRow> originals = repository.findSettlementDetailsByTxn(txnNo);
        Map<String, Long> refundedByLine = new HashMap<>();
        for (LineAmountRow row : repository.sumAdjustedByLineForTxn(txnNo)) {
            refundedByLine.put(row.lineCode(), -row.amountCents());
        }
        long fareCents = originals.stream().mapToLong(DetailRow::amountCents).sum();
        List<LineBalanceResponse.LineBalance> lines = new ArrayList<>();
        long refundedTotal = 0L;
        for (DetailRow detail : originals) {
            long refunded = refundedByLine.getOrDefault(detail.lineCode(), 0L);
            long remaining = detail.amountCents() - refunded;
            refundedTotal += refunded;
            lines.add(new LineBalanceResponse.LineBalance(detail.lineCode(), detail.ratio(),
                    detail.amountCents(), refunded, remaining));
        }
        return new LineBalanceResponse(txnNo, txn.fareCents() == null ? fareCents : txn.fareCents(),
                refundedTotal, txn.fareCents() == null ? fareCents - refundedTotal
                        : txn.fareCents() - Math.min(refundedTotal, txn.fareCents()),
                sealed, settled, lines);
    }

    /** 查询退款单视图。 */
    public RefundViewResponse refundView(String refundNo) {
        RefundRow refund = repository.findRefundByNo(refundNo)
                .orElseThrow(() -> MetroException.notFound("REFUND_NOT_FOUND", "退款单不存在: " + refundNo));
        String batchNo = null;
        if (refund.adjustmentBatchId() != null) {
            batchNo = repository.findAdjustmentBatchById(refund.adjustmentBatchId())
                    .map(AdjustmentBatchRow::batchNo).orElse(null);
        }
        List<RefundConfirmResponse.LineAdjustmentView> lines = new ArrayList<>();
        for (AdjustmentDetailRow d : repository.findAdjustmentDetailsByRefund(refundNo)) {
            lines.add(new RefundConfirmResponse.LineAdjustmentView(d.lineCode(), d.ratio(),
                    -d.amountCents()));
        }
        return new RefundViewResponse(refund.refundNo(), refund.txnNo(), refund.amountCents(),
                refund.status(), refund.version(), refund.reviewerOne(), refund.reviewerTwo(),
                batchNo, lines);
    }

    // ============================ 业务实现 ============================

    private RefundApplyResponse doApply(RefundApplyRequest request) {
        if (request.amountCents() <= 0L) {
            throw MetroException.badRequest("REFUND_AMOUNT_INVALID", "退款金额必须为正（分）");
        }
        TxnRow txn = repository.findTxnByNo(request.txnNo())
                .orElseThrow(() -> MetroException.notFound("TXN_NOT_FOUND",
                        "交易流水不存在: " + request.txnNo()));
        assertTripRefundable(txn);
        long fareCents = txn.fareCents() == null ? 0L : txn.fareCents();
        long refunded = repository.sumConfirmedRefundsByTxn(txn.txnNo());
        if (request.amountCents() > fareCents - refunded) {
            throw MetroException.unprocessable("REFUND_EXCEEDS_FARE",
                    "累计退款不得超过原实收: 原实收 " + fareCents + " 已退 " + refunded
                            + " 本次申请 " + request.amountCents());
        }
        repository.insertRefund(new RefundRow(null, request.refundNo(), request.txnNo(),
                request.amountCents(), "PENDING", 1, null, null, request.requestId(), null, null,
                null));
        return new RefundApplyResponse(request.refundNo(), request.txnNo(), request.amountCents(),
                "PENDING", 1, false);
    }

    private RefundConfirmResponse doConfirm(RefundConfirmRequest request, List<String> reviewers) {
        RefundRow refund = repository.findRefundByNoForUpdate(request.refundNo())
                .orElseThrow(() -> MetroException.notFound("REFUND_NOT_FOUND",
                        "退款单不存在: " + request.refundNo()));
        if (refund.version() != request.expectedVersion()) {
            throw MetroException.conflict("VERSION_CONFLICT",
                    "退款单版本不匹配: 期望 " + request.expectedVersion() + " 实际 " + refund.version());
        }
        if ("CONFIRMED".equals(refund.status())) {
            throw MetroException.unprocessable("REFUND_ALREADY_CONFIRMED",
                    "退款单已确认，单人重复操作不生效: " + request.refundNo());
        }
        String reviewerOne = reviewers.get(0);
        String reviewerTwo = reviewers.get(1);
        if (reviewerOne.equals(reviewerTwo)) {
            throw MetroException.badRequest("REVIEWER_SAME", "两名复核人不得相同");
        }

        // 锁定原行程行：同一行程的并发确认在此串行，先提交者占用可退余额
        TxnRow txn = repository.findTxnByNoForUpdate(refund.txnNo())
                .orElseThrow(() -> MetroException.notFound("TXN_NOT_FOUND",
                        "交易流水不存在: " + refund.txnNo()));
        assertTripRefundable(txn);
        long fareCents = txn.fareCents() == null ? 0L : txn.fareCents();
        long alreadyRefunded = repository.sumConfirmedRefundsByTxn(txn.txnNo());
        if (refund.amountCents() > fareCents - alreadyRefunded) {
            throw MetroException.unprocessable("REFUND_EXCEEDS_FARE",
                    "累计退款不得超过原实收: 原实收 " + fareCents + " 已退 " + alreadyRefunded
                            + " 本次 " + refund.amountCents());
        }

        List<DetailRow> originals = repository.findSettlementDetailsByTxn(txn.txnNo());
        if (originals.isEmpty()) {
            throw MetroException.unprocessable("REFUND_NO_SETTLEMENT_DETAIL",
                    "原行程缺少按实结算清分明细，不可退款: " + txn.txnNo());
        }
        Map<String, Long> adjustedByLine = new HashMap<>();
        for (LineAmountRow row : repository.sumAdjustedByLineForTxn(txn.txnNo())) {
            adjustedByLine.put(row.lineCode(), row.amountCents());
        }
        Map<String, Long> originalByLine = new HashMap<>();
        Map<String, String> ratioByLine = new HashMap<>();
        for (DetailRow d : originals) {
            originalByLine.merge(d.lineCode(), d.amountCents(), Long::sum);
            ratioByLine.putIfAbsent(d.lineCode(), d.ratio());
        }
        Map<String, Long> allocation = allocateRefund(refund.amountCents(), originals,
                originalByLine, adjustedByLine);

        long allocated = allocation.values().stream().mapToLong(Long::longValue).sum();
        if (allocated != refund.amountCents()) {
            throw new IllegalStateException("退款分摊合计不等于退款额: " + allocated + " != "
                    + refund.amountCents());
        }
        for (Map.Entry<String, Long> entry : allocation.entrySet()) {
            repository.insertAdjustmentDetail(new AdjustmentDetailRow(null, refund.refundNo(),
                    txn.txnNo(), entry.getKey(), ratioByLine.get(entry.getKey()),
                    -entry.getValue()));
        }
        repository.confirmRefund(refund.id(), reviewerOne, reviewerTwo, request.requestId(),
                request.confirmTime());

        List<RefundConfirmResponse.LineAdjustmentView> lines = new ArrayList<>();
        for (DetailRow d : originals) {
            Long amount = allocation.get(d.lineCode());
            if (amount != null) {
                lines.add(new RefundConfirmResponse.LineAdjustmentView(d.lineCode(), d.ratio(), amount));
            }
        }
        return new RefundConfirmResponse(refund.refundNo(), txn.txnNo(), "CONFIRMED",
                refund.version() + 1, refund.amountCents(), reviewerOne, reviewerTwo, lines, false);
    }

    private AdjustmentIncludeResponse doInclude(AdjustmentIncludeRequest request) {
        RefundRow refund = repository.findRefundByNoForUpdate(request.refundNo())
                .orElseThrow(() -> MetroException.notFound("REFUND_NOT_FOUND",
                        "退款单不存在: " + request.refundNo()));
        if (refund.version() != request.expectedVersion()) {
            throw MetroException.conflict("VERSION_CONFLICT",
                    "退款单版本不匹配: 期望 " + request.expectedVersion() + " 实际 " + refund.version());
        }
        if (!"CONFIRMED".equals(refund.status())) {
            throw MetroException.unprocessable("REFUND_NOT_CONFIRMED",
                    "退款单未经双人确认，不可纳入调账批次: " + request.refundNo());
        }

        // 已纳入：幂等成功，不重复计额、不改挂批次
        if (refund.adjustmentBatchId() != null) {
            AdjustmentBatchRow attached = repository.findAdjustmentBatchById(
                    refund.adjustmentBatchId()).orElseThrow();
            return new AdjustmentIncludeResponse(refund.refundNo(), attached.batchNo(),
                    attached.status(), attached.version(), attached.totalCents(),
                    attached.orderCount(), false, false);
        }

        AdjustmentBatchRow batch = getOrCreateOpenBatchForUpdate();
        if (!"OPEN".equals(batch.status())) {
            throw MetroException.unprocessable("ADJUSTMENT_BATCH_SEALED",
                    "调账批次已封存，不可再纳入: " + batch.batchNo());
        }
        long deltaCents = repository.sumAdjustmentDetailsByRefund(refund.refundNo());
        repository.addAdjustmentToBatch(batch.id(), deltaCents);
        repository.attachRefundBatch(refund.id(), batch.id());
        AdjustmentBatchRow updated = repository.findAdjustmentBatchById(batch.id()).orElseThrow();
        return new AdjustmentIncludeResponse(refund.refundNo(), updated.batchNo(),
                updated.status(), updated.version(), updated.totalCents(), updated.orderCount(),
                true, false);
    }

    private AdjustmentSealResponse doSealBatch(AdjustmentSealRequest request) {
        AdjustmentBatchRow batch = repository.findAdjustmentBatchByNoForUpdate(request.batchNo())
                .orElseThrow(() -> MetroException.notFound("ADJUSTMENT_BATCH_NOT_FOUND",
                        "调账批次不存在: " + request.batchNo()));
        if ("SEALED".equals(batch.status())) {
            return new AdjustmentSealResponse(batch.batchNo(), "SEALED", batch.version(),
                    batch.totalCents(), batch.orderCount(), false);
        }
        if (batch.version() != request.expectedVersion()) {
            throw MetroException.conflict("VERSION_CONFLICT",
                    "调账批次版本不匹配: 期望 " + request.expectedVersion() + " 实际 "
                            + batch.version());
        }
        var totals = repository.recalcAdjustmentBatchTotal(batch.id());
        repository.sealAdjustmentBatch(batch.id(), totals.totalCents(), totals.orderCount(),
                request.requestId(), request.sealTime());
        AdjustmentBatchRow sealed = repository.findAdjustmentBatchByNo(request.batchNo()).orElseThrow();
        return new AdjustmentSealResponse(sealed.batchNo(), "SEALED", sealed.version(),
                sealed.totalCents(), sealed.orderCount(), false);
    }

    private CardCloseResponse doCloseCard(CardCloseRequest request) {
        CardRow card = repository.findCardByIdForUpdate(request.cardId())
                .orElseThrow(() -> MetroException.notFound("CARD_NOT_FOUND",
                        "票卡不存在: " + request.cardId()));
        if ("CLOSED".equals(card.status())) {
            return new CardCloseResponse(card.cardId(), "CLOSED", card.version(), false);
        }
        if (card.version() != request.expectedVersion()) {
            throw MetroException.conflict("VERSION_CONFLICT",
                    "票卡版本不匹配: 期望 " + request.expectedVersion() + " 实际 " + card.version());
        }
        repository.closeCard(card.cardId(), request.requestId(), request.closeTime());
        return new CardCloseResponse(card.cardId(), "CLOSED", card.version() + 1, false);
    }

    /**
     * 校验行程可退款：必须已按实结算（COMPLETED），且原清分批次已封账；
     * 未出闸暂记（ENTERED/ESTIMATED）不可退款。
     */
    private void assertTripRefundable(TxnRow txn) {
        if (!"COMPLETED".equals(txn.status())) {
            throw MetroException.unprocessable("REFUND_TRIP_NOT_SETTLED",
                    "仅已按实结算行程可退款，未出闸或暂记行程不可退: " + txn.txnNo()
                            + " 当前状态 " + txn.status());
        }
        if (txn.batchId() == null) {
            throw MetroException.unprocessable("REFUND_TRIP_NOT_SEALED",
                    "行程未入账已封账批次，不可退款: " + txn.txnNo());
        }
        BatchRow batch = repository.findBatchById(txn.batchId())
                .orElseThrow(() -> new IllegalStateException("原清分批次缺失: " + txn.batchId()));
        if (!"SEALED".equals(batch.status())) {
            throw MetroException.unprocessable("REFUND_TRIP_NOT_SEALED",
                    "原清分批次尚未封账，不可退款: " + txn.txnNo() + " 业务日期 " + batch.bizDate());
        }
    }

    /**
     * 按每条原线路实收份额分摊本次退款：
     * 先对各线路按份额向下取整并限制到该线路可退余额，剩余分逐一分给尚有可退余额的
     * 线路，按原份额降序、线路编号升序循环，直到分完。
     *
     * @return 线路到本次退款分摊（正数）的映射，合计恰等于退款额，且各线路累计不超原份额
     */
    private Map<String, Long> allocateRefund(long refundCents, List<DetailRow> originalDetails,
                                             Map<String, Long> originalByLine,
                                             Map<String, Long> adjustedByLine) {
        long originalTotal = originalByLine.values().stream().mapToLong(Long::longValue).sum();
        List<String> lines = new ArrayList<>(originalByLine.keySet());
        Map<String, Long> remainingByLine = new HashMap<>();
        for (String line : lines) {
            long remaining = originalByLine.get(line) + adjustedByLine.getOrDefault(line, 0L);
            if (remaining < 0L) {
                throw new IllegalStateException("线路已退超过原份额: " + line);
            }
            remainingByLine.put(line, remaining);
        }
        Map<String, Long> allocation = new HashMap<>();
        long assigned = 0L;
        BigDecimal totalDecimal = BigDecimal.valueOf(originalTotal);
        for (String line : lines) {
            BigDecimal share = BigDecimal.valueOf(refundCents)
                    .multiply(BigDecimal.valueOf(originalByLine.get(line)))
                    .divide(totalDecimal, 0, RoundingMode.FLOOR);
            long amount = Math.min(share.longValue(), remainingByLine.get(line));
            amount = Math.max(0L, amount);
            allocation.put(line, amount);
            assigned += amount;
        }
        long leftover = refundCents - assigned;
        List<String> roundRobinOrder = lines.stream()
                .sorted(Comparator.comparingLong((String l) -> originalByLine.get(l)).reversed()
                        .thenComparing(l -> l))
                .toList();
        int cursor = 0;
        int guard = 0;
        while (leftover > 0) {
            if (guard++ > lines.size() * (refundCents + 1)) {
                throw new IllegalStateException("退款尾差分摊无法收敛");
            }
            String line = roundRobinOrder.get(cursor % roundRobinOrder.size());
            cursor++;
            if (allocation.get(line) < remainingByLine.get(line)) {
                allocation.merge(line, 1L, Long::sum);
                leftover--;
            }
            if (cursor > roundRobinOrder.size() * (refundCents + 2)) {
                throw MetroException.unprocessable("REFUND_EXCEEDS_FARE",
                        "线路可退余额不足，无法完成分摊");
            }
        }
        return allocation;
    }

    /** 取得唯一开放调账批次并加锁；不存在则在锁内创建，并发创建以唯一索引仲裁。 */
    private AdjustmentBatchRow getOrCreateOpenBatchForUpdate() {
        Optional<AdjustmentBatchRow> existing = repository.findOpenAdjustmentBatchForUpdate();
        if (existing.isPresent()) {
            return existing.get();
        }
        try {
            long id = repository.insertAdjustmentBatch("TMP-" + java.util.UUID.randomUUID());
            String batchNo = String.format("AJB%06d", id);
            repository.updateAdjustmentBatchNo(id, batchNo);
        } catch (DuplicateKeyException ex) {
            // 并发开立：开放唯一索引仲裁，重新加锁读取
        }
        return repository.findOpenAdjustmentBatchForUpdate()
                .orElseThrow(() -> new IllegalStateException("开放调账批次创建失败"));
    }

    // ============================ 幂等与指纹 ============================

    private <T extends ReplayableResponse<T>> T idempotent(
            String scope, String requestId, String fingerprint, Class<T> type,
            Supplier<T> action, Supplier<RuntimeException> onUniqueRace) {
        Optional<IdemRow> existing = repository.findIdem(scope, requestId);
        if (existing.isPresent()) {
            return replay(existing.get(), fingerprint, type);
        }
        try {
            return txTemplate.execute(status -> {
                repository.insertIdemPlaceholder(scope, requestId, fingerprint);
                T response = action.get();
                repository.updateIdemResponse(scope, requestId, toJson(response));
                return response;
            });
        } catch (DuplicateKeyException ex) {
            return repository.findIdem(scope, requestId)
                    .map(row -> replay(row, fingerprint, type))
                    .orElseThrow(onUniqueRace);
        }
    }

    private <T extends ReplayableResponse<T>> T replay(IdemRow row, String fingerprint, Class<T> type) {
        if (!row.fingerprint().equals(fingerprint)) {
            throw MetroException.conflict("IDEMPOTENCY_CONFLICT",
                    "相同 requestId 但业务参数（版本/集合/时刻）不一致，拒绝重复执行");
        }
        try {
            return objectMapper.readValue(row.responseBody(), type).asReplayed();
        } catch (JsonProcessingException ex) {
            throw new IllegalStateException("幂等响应反序列化失败", ex);
        }
    }

    private String toJson(Object response) {
        try {
            return objectMapper.writeValueAsString(response);
        } catch (JsonProcessingException ex) {
            throw new IllegalStateException("幂等响应序列化失败", ex);
        }
    }

    /**
     * 结构化指纹：以 JSON 数组固定字段顺序承载（集合先排序），文本内含分隔符时
     * 由 JSON 转义无歧义区分，最后取 SHA-256。
     */
    private String fingerprint(List<Object> canonicalParts) {
        try {
            String canonical = objectMapper.writeValueAsString(canonicalParts);
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            byte[] hash = digest.digest(canonical.getBytes(StandardCharsets.UTF_8));
            StringBuilder hex = new StringBuilder(hash.length * 2);
            for (byte b : hash) {
                hex.append(Character.forDigit((b >> 4) & 0xF, 16));
                hex.append(Character.forDigit(b & 0xF, 16));
            }
            return hex.toString();
        } catch (NoSuchAlgorithmException | JsonProcessingException ex) {
            throw new IllegalStateException("指纹计算失败", ex);
        }
    }
}

