                                             @Valid @RequestBody AdjustmentIncludeRequest request) {
        return refundService.include(request);
    }

    /** 查询退款单。 */
    @GetMapping("/refunds/{refundNo}")
    public RefundViewResponse refundView(@PathVariable String refundNo) {
        return refundService.refundView(refundNo);
    }

    /** 查询行程逐线路退款余额。 */
    @GetMapping("/transactions/{txnNo}/line-balances")
    public LineBalanceResponse lineBalances(@PathVariable String txnNo) {
        return refundService.lineBalances(txnNo);
    }

    /** 封存调账批次。 */
    @PostMapping("/adjustment-batches/{batchNo}/seal")
    public AdjustmentSealResponse sealBatch(@PathVariable String batchNo,
                                            @Valid @RequestBody AdjustmentSealRequest request) {
        return refundService.sealBatch(request);
    }

    /** 关闭票卡。 */
    @PostMapping("/cards/{cardId}/close")
    public CardCloseResponse closeCard(@PathVariable String cardId,
                                       @Valid @RequestBody CardCloseRequest request) {
        return refundService.closeCard(request);
    }
}

