import com.example.starter.metro.dto.AdjustmentSealResponse;
import com.example.starter.metro.dto.CardCloseRequest;
import com.example.starter.metro.dto.CardCloseResponse;
import com.example.starter.metro.dto.LineBalanceResponse;
import com.example.starter.metro.dto.RefundApplyRequest;
import com.example.starter.metro.dto.RefundApplyResponse;
import com.example.starter.metro.dto.RefundConfirmRequest;
import com.example.starter.metro.dto.RefundConfirmResponse;
import com.example.starter.metro.dto.RefundViewResponse;
import jakarta.validation.Valid;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

/**
 * 封账行程退款冲正 API：申请、双人确认、调账纳入/封存、逐线路余额查询、票卡关闭。
 */
@RestController
@RequestMapping("/api/metro")
public class RefundController {

    private final RefundService refundService;

    public RefundController(RefundService refundService) {
        this.refundService = refundService;
    }

    /** 退款申请。 */
    @PostMapping("/refunds")
    public RefundApplyResponse apply(@Valid @RequestBody RefundApplyRequest request) {
        return refundService.apply(request);
    }

    /** 双人确认（同一事务共同校验生效）。 */
    @PostMapping("/refunds/{refundNo}/confirm")
    public RefundConfirmResponse confirm(@PathVariable String refundNo,
                                         @Valid @RequestBody RefundConfirmRequest request) {
        if (!refundNo.equals(request.refundNo())) {
            throw MetroException.badRequest("PATH_BODY_MISMATCH",
                    "路径退款单号与请求体不一致");
        }
        return refundService.confirm(request);
    }

    /** 纳入开放调账批次。 */
    @PostMapping("/refunds/{refundNo}/include")
    public AdjustmentIncludeResponse include(@PathVariable String refundNo,
                                             @Valid @RequestBody AdjustmentIncludeRequest request) {
        if (!refundNo.equals(request.refundNo())) {
            throw MetroException.badRequest("PATH_BODY_MISMATCH",
                    "路径退款单号与请求体不一致");
        }
        return refundService.include(request);
    }

    /** 查询退款单。 */
    @GetMapping("/refunds/{refundNo}")
    public RefundViewResponse refundView(@PathVariable String refundNo) {
        return refundService.refundView(refundNo);
    }

    /** 查询行程逐线路退款余额。 */
    @GetMapping("/transactions/{txnNo}/line-balances")
    public LineBalanceResponse lineBalances(@PathVariable String txnNo) {
        return refundService.lineBalances(txnNo);
    }

    /** 封存调账批次。 */
    @PostMapping("/adjustment-batches/{batchNo}/seal")
    public AdjustmentSealResponse sealBatch(@PathVariable String batchNo,
                                            @Valid @RequestBody AdjustmentSealRequest request) {
        return refundService.sealBatch(request);
    }

    /** 关闭票卡。 */
    @PostMapping("/cards/{cardId}/close")
    public CardCloseResponse closeCard(@PathVariable String cardId,
                                       @Valid @RequestBody CardCloseRequest request) {
        return refundService.closeCard(request);
    }
}

