        // 再申请 300：超出剩余可退 200，申请即 422
        JsonNode over = call(422, "/api/metro/refunds", new RefundApplyRequest("ra2b", "RFD2B",
                "T2", 300L, LocalDateTime.of(2026, 9, 26, 9, 2)));
        assertEquals("REFUND_EXCEEDS_FARE", over.get("code").asText());

        // 恰退满剩余 200：L1 floor 75 / L2 封顶 124，尾差 1 分给尚有余额的 L1
        call(200, "/api/metro/refunds", new RefundApplyRequest("ra2c", "RFD2C", "T2", 200L,
                LocalDateTime.of(2026, 9, 26, 9, 3)));
        JsonNode c2 = call(200, "/api/metro/refunds/RFD2C/confirm",
                new RefundConfirmRequest("rc2c", "RFD2C", 1,
                        java.util.Set.of("u1", "u2"), LocalDateTime.of(2026, 9, 26, 9, 4)));
        assertLine(c2, "L1", 76L);
