        // 各线路累计恰等于原份额，总可退为 0
        JsonNode balances = getJson(200, "/api/metro/transactions/T2/line-balances");
        assertEquals(0L, balances.get("remainingCents").asLong());
        for (JsonNode line : balances.get("lines")) {
            assertEquals(0L, line.get("remainingCents").asLong());
            assertEquals(line.get("originalCents").asLong(), line.get("refundedCents").asLong());
        }

        // 退满后再退 1 分：422
        JsonNode full = call(422, "/api/metro/refunds", new RefundApplyRequest("ra2d", "RFD2D",
                "T2", 1L, LocalDateTime.of(2026, 9, 26, 9, 5)));
        assertEquals("REFUND_EXCEEDS_FARE", full.get("code").asText());
    }

