                new RefundConfirmRequest("rc5a", "RFD5", 2,
                        java.util.Set.of("u1", "u2"), LocalDateTime.of(2026, 9, 26, 9, 1)));
        assertEquals("VERSION_CONFLICT", badVersion.get("code").asText());

        // 两名复核人相同（集合去重后不足 2 人）-> 400
        JsonNode sameReviewer = callRaw(400, "/api/metro/refunds/RFD5/confirm",
