    private void assertLine(JsonNode confirmResponse, String lineCode, long expectedCents) {
        for (JsonNode line : confirmResponse.get("lines")) {
            if (lineCode.equals(line.get("lineCode").asText())) {
                assertEquals(expectedCents, line.get("amountCents").asLong(),
                        "线路 " + lineCode + " 分摊金额不符");
                return;
            }
        }
        throw new AssertionError("缺少线路分摊: " + lineCode);
    }
