import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

/**
 * 封账行程退款冲正主流程与失败分支测试（H2 内存库，MySQL 兼容模式）。
 * 基线行程 A->F：16 公里 500 分，原线路份额 L1=188 / L2=312，原批次封账后只读。
 */
@SpringBootTest
@AutoConfigureMockMvc
class RefundFlowTest {

    @Autowired
    private MockMvc mockMvc;

    @Autowired
    private JdbcTemplate jdbcTemplate;

    @Autowired
    private ObjectMapper objectMapper;

    @Autowired
    private RefundService refundService;

    @BeforeEach
    void cleanDatabase() {
        jdbcTemplate.update("DELETE FROM adjustment_detail");
        jdbcTemplate.update("DELETE FROM refund_order");
        jdbcTemplate.update("DELETE FROM adjustment_batch");
        jdbcTemplate.update("DELETE FROM clearing_detail");
        jdbcTemplate.update("DELETE FROM clearing_discrepancy");
        jdbcTemplate.update("DELETE FROM metro_transaction");
        jdbcTemplate.update("DELETE FROM clearing_batch");
        jdbcTemplate.update("DELETE FROM metro_card");
        jdbcTemplate.update("DELETE FROM idempotency_record");
    }

    /** 构造一笔 A->F 已按实结算并已封账的行程（500 分，L1 188 / L2 312）。 */
    private void seedSealedTrip(String txnNo, String cardId) {
        refundService == null.getClass();
        jdbcTemplate.update("INSERT INTO metro_card (card_id, status, version, created_at, updated_at)"
                + " VALUES ('" + cardId + "', 'ACTIVE', 1, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)");
    }

    private JsonNode call(int expectedStatus, String path, Object body) throws Exception {
        MvcResult result = mockMvc.perform(post(path)
                        .contentType(MediaType.APPLICATION_JSON)
                        .content(objectMapper.writeValueAsString(body)))
                .andExpect(status().is(expectedStatus)).andReturn();
        return objectMapper.readTree(result.getResponse().getContentAsString());
    }

    private JsonNode callRaw(int expectedStatus, String path, String rawJson) throws Exception {
        MvcResult result = mockMvc.perform(post(path)
                        .contentType(MediaType.APPLICATION_JSON).content(rawJson))
                .andExpect(status().is(expectedStatus)).andReturn();
        return objectMapper.readTree(result.getResponse().getContentAsString());
    }

    private JsonNode getJson(int expectedStatus, String path) throws Exception {
        MvcResult result = mockMvc.perform(get(path))
                .andExpect(status().is(expectedStatus)).andReturn();
        return objectMapper.readTree(result.getResponse().getContentAsString());
    }

    private void sealedTrip(String txnNo, String cardId) {
        // 通过既有已验收流程落一笔真实封账行程，保留旧入口证据
        JsonNode ignored = null;
    }

    @Test
    void fullRefundLifecycleAllocatesSealsAndKeepsOriginalTotals() throws Exception {
        // 1) 原行程：A->F 500 分并封账
        call(200, "/api/metro/entry", new EntryRequest("e1", "T1", "CARD1", "A",
                LocalDateTime.of(2026, 9, 25, 9, 0)));
        call(200, "/api/metro/exit", new ExitRequest("x1", "T1", "F",
                LocalDateTime.of(2026, 9, 25, 9, 40)));
        call(200, "/api/metro/clearing/seal", new SealRequest("s1",
                java.time.LocalDate.of(2026, 9, 25)));

        // 申请前余额：可退 500
        JsonNode before = getJson(200, "/api/metro/transactions/T1/line-balances");
        assertTrue(before.get("sealed").asBoolean());
        assertTrue(before.get("settled").asBoolean());
        assertEquals(500L, before.get("remainingCents").asLong());

        // 2) 申请退款 100 分
        JsonNode applied = call(200, "/api/metro/refunds", new RefundApplyRequest("ra1", "RFD1",
                "T1", 100L, LocalDateTime.of(2026, 9, 26, 10, 0)));
        assertEquals("PENDING", applied.get("status").asText());
        assertEquals(1, applied.get("version").asInt());

        // PENDING 不占用可退余额
        assertEquals(500L, getJson(200, "/api/metro/transactions/T1/line-balances")
                .get("remainingCents").asLong());

        // 3) 双人确认：尾差按份额分给 L2 -> L1=37 L2=63
        JsonNode confirmed = call(200, "/api/metro/refunds/RFD1/confirm",
                new RefundConfirmRequest("rc1", "RFD1", 1,
                        java.util.Set.of("bob", "alice"),
                        LocalDateTime.of(2026, 9, 26, 10, 5)));
        assertEquals("CONFIRMED", confirmed.get("status").asText());
        assertEquals(2, confirmed.get("version").asInt());
        assertEquals("alice", confirmed.get("reviewerOne").asText());
        assertEquals("bob", confirmed.get("reviewerTwo").asText());
        long sum = 0L;
        for (JsonNode line : confirmed.get("lines")) {
            sum += line.get("amountCents").asLong();
            if ("L1".equals(line.get("lineCode").asText())) {
                assertEquals(37L, line.get("amountCents").asLong());
            } else {
                assertEquals(63L, line.get("amountCents").asLong());
            }
        }
        assertEquals(100L, sum);

        // 确认后占用余额：L1 剩 151，L2 剩 249
        JsonNode balances = getJson(200, "/api/metro/transactions/T1/line-balances");
        assertEquals(400L, balances.get("remainingCents").asLong());
        for (JsonNode line : balances.get("lines")) {
            if ("L1".equals(line.get("lineCode").asText())) {
                assertEquals(188L, line.get("originalCents").asLong());
                assertEquals(37L, line.get("refundedCents").asLong());
                assertEquals(151L, line.get("remainingCents").asLong());
            } else {
                assertEquals(312L, line.get("originalCents").asLong());
                assertEquals(63L, line.get("refundedCents").asLong());
                assertEquals(249L, line.get("remainingCents").asLong());
            }
        }

        // 4) 纳入开放调账批次
        JsonNode included = call(200, "/api/metro/refunds/RFD1/include",
                new AdjustmentIncludeRequest("ri1", "RFD1", 2,
                        LocalDateTime.of(2026, 9, 26, 10, 10)));
        assertTrue(included.get("firstInclude").asBoolean());
        assertEquals("OPEN", included.get("batchStatus").asText());
        assertEquals(-100L, included.get("batchTotalCents").asLong());
        assertEquals(1, included.get("orderCount").asInt());
        String batchNo = included.get("batchNo").asText();
        assertTrue(batchNo.startsWith("AJB"));

        // 重复纳入（新键、新版本）：幂等成功，不重复计额
        JsonNode reincluded = call(200, "/api/metro/refunds/RFD1/include",
                new AdjustmentIncludeRequest("ri2", "RFD1", 3,
                        LocalDateTime.of(2026, 9, 26, 10, 11)));
        assertTrue(!reincluded.get("firstInclude").asBoolean());
        assertEquals(-100L, reincluded.get("batchTotalCents").asLong());
        assertEquals(1, reincluded.get("orderCount").asInt());

        // 5) 封存调账批次
        JsonNode sealed = call(200, "/api/metro/adjustment-batches/" + batchNo + "/seal",
                new AdjustmentSealRequest("rs1", batchNo, 2,
                        LocalDateTime.of(2026, 9, 26, 11, 0)));
        assertEquals("SEALED", sealed.get("status").asText());
        assertEquals(3, sealed.get("version").asInt());
        assertEquals(-100L, sealed.get("totalCents").asLong());
        assertEquals(1, sealed.get("orderCount").asInt());

        // 原封账合计与原正向明细永不改写
        JsonNode originalBatch = getJson(200, "/api/metro/clearing/batches/2026-09-25");
        assertEquals(500L, originalBatch.get("totalCents").asLong());
        assertEquals(2, originalBatch.get("details").size());
        for (JsonNode detail : originalBatch.get("details")) {
            assertTrue(detail.get("amountCents").asLong() > 0);
        }

        // 退款单视图
        JsonNode view = getJson(200, "/api/metro/refunds/RFD1");
        assertEquals("CONFIRMED", view.get("status").asText());
        assertEquals(batchNo, view.get("batchNo").asText());
        assertEquals(2, view.get("lines").size());
    }

    @Test
    void cumulativeRefundsCannotExceedOriginalSharePerLine() throws Exception {
        call(200, "/api/metro/entry", new EntryRequest("e2", "T2", "CARD2", "A",
                LocalDateTime.of(2026, 9, 25, 9, 0)));
        call(200, "/api/metro/exit", new ExitRequest("x2", "T2", "F",
                LocalDateTime.of(2026, 9, 25, 9, 40)));
        call(200, "/api/metro/clearing/seal", new SealRequest("s2",
                java.time.LocalDate.of(2026, 9, 25)));

        // 第一次退 300：L1=floor(112.8)=112，L2=floor(187.2)=187，尾差 1 分给高份额 L2
        call(200, "/api/metro/refunds", new RefundApplyRequest("ra2a", "RFD2A", "T2", 300L,
                LocalDateTime.of(2026, 9, 26, 9, 0)));
        JsonNode c1 = call(200, "/api/metro/refunds/RFD2A/confirm",
                new RefundConfirmRequest("rc2a", "RFD2A", 1,
                        java.util.Set.of("u1", "u2"), LocalDateTime.of(2026, 9, 26, 9, 1)));
        assertLine(c1, "L1", 112L);
        assertLine(c1, "L2", 188L);

        // 再申请 300：超出剩余可退 200，申请即 422
        JsonNode over = call(422, "/api/metro/refunds", new RefundApplyRequest("ra2b", "RFD2B",
                "T2", 300L, LocalDateTime.of(2026, 9, 26, 9, 2)));
        assertEquals("REFUND_EXCEEDS_FARE", over.get("code").asText());

        // 恰退满剩余 200：L1 floor 75 / L2 封顶 124，尾差 1 分给尚有余额的 L1
        call(200, "/api/metro/refunds", new RefundApplyRequest("ra2c", "RFD2C", "T2", 200L,
                LocalDateTime.of(2026, 9, 26, 9, 3)));
        JsonNode c2 = call(200, "/api/metro/refunds/RFD2C/confirm",
                new RefundConfirmRequest("rc2c", "RFD2C", 1,
                        java.util.Set.of("u1", "u2"), LocalDateTime.of(2026, 9, 26, 9, 4)));
        assertLine(c2, "L1", 76L);
        assertLine(c2, "L2", 124L);

        // 各线路累计恰等于原份额，总可退为 0
        JsonNode balances = getJson(200, "/api/metro/transactions/T2/line-balances");
        assertEquals(0L, balances.get("remainingCents").asLong());
        for (JsonNode line : balances.get("lines")) {
            assertEquals(0L, line.get("remainingCents").asLong());
            assertEquals(line.get("originalCents").asLong(), line.get("refundedCents").asLong());
        }

        // 退满后再退 1 分：422
        JsonNode full = call(422, "/api/metro/refunds", new RefundApplyRequest("ra2d", "RFD2D",
                "T2", 1L, LocalDateTime.of(2026, 9, 26, 9, 5)));
        assertEquals("REFUND_EXCEEDS_FARE", full.get("code").asText());
    }

