    @Test
    void confirmationEnforcesVersionReviewersAndState() throws Exception {
        call(200, "/api/metro/entry", new EntryRequest("e5", "T5", "CARD5", "A",
                LocalDateTime.of(2026, 9, 25, 9, 0)));
        call(200, "/api/metro/exit", new ExitRequest("x5", "T5", "F",
                LocalDateTime.of(2026, 9, 25, 9, 40)));
        call(200, "/api/metro/clearing/seal", new SealRequest("s5",
                java.time.LocalDate.of(2026, 9, 25)));
        call(200, "/api/metro/refunds", new RefundApplyRequest("ra5", "RFD5", "T5", 100L,
                LocalDateTime.of(2026, 9, 26, 9, 0)));

        // 退款单不存在
        JsonNode notFound = call(404, "/api/metro/refunds/NOPE/confirm",
                new RefundConfirmRequest("rc5x", "NOPE", 1,
                        java.util.Set.of("u1", "u2"), LocalDateTime.of(2026, 9, 26, 9, 1)));
        assertEquals("REFUND_NOT_FOUND", notFound.get("code").asText());

        // 版本不匹配 -> 409
        JsonNode badVersion = call(409, "/api/metro/refunds/RFD5/confirm",
                new RefundConfirmRequest("rc5a", "RFD5", 2,
                        java.util.Set.of("u1", "u2"), LocalDateTime.of(2026, 9, 26, 9, 1)));
        assertEquals("VERSION_CONFLICT", badVersion.get("code").asText());

        // 两名复核人相同（集合去重后不足 2 人）-> 400
        JsonNode sameReviewer = callRaw(400, "/api/metro/refunds/RFD5/confirm",
                "{\"requestId\":\"rc5b\",\"refundNo\":\"RFD5\",\"expectedVersion\":1,"
                        + "\"reviewers\":[\"u1\",\"u1\"],\"confirmTime\":\"2026-09-26T09:01:00\"}");
        assertEquals("VALIDATION_FAILED", sameReviewer.get("code").asText());

        // 合法确认
        call(200, "/api/metro/refunds/RFD5/confirm",
                new RefundConfirmRequest("rc5c", "RFD5", 1,
                        java.util.Set.of("u1", "u2"), LocalDateTime.of(2026, 9, 26, 9, 2)));

        // 单人重复确认（新键、当前版本）-> 422，不重复生效
        JsonNode again = call(422, "/api/metro/refunds/RFD5/confirm",
                new RefundConfirmRequest("rc5d", "RFD5", 2,
                        java.util.Set.of("u3", "u4"), LocalDateTime.of(2026, 9, 26, 9, 3)));
        assertEquals("REFUND_ALREADY_CONFIRMED", again.get("code").asText());

        // 负向明细仍只有两条、合计 -100
        Long detailCount = jdbcTemplate.queryForObject(
                "SELECT COUNT(*) FROM adjustment_detail WHERE refund_no = 'RFD5'", Long.class);
        assertEquals(2L, detailCount);
        Long total = jdbcTemplate.queryForObject(
                "SELECT COALESCE(SUM(amount_cents),0) FROM adjustment_detail WHERE refund_no = 'RFD5'",
                Long.class);
        assertEquals(-100L, total);
    }

