    @Test
    void idempotencyReplaysSameParamsAndRejectsDifferentParams() throws Exception {
        call(200, "/api/metro/entry", new EntryRequest("e7", "T7", "CARD7", "A",
                LocalDateTime.of(2026, 9, 25, 9, 0)));
        call(200, "/api/metro/exit", new ExitRequest("x7", "T7", "F",
                LocalDateTime.of(2026, 9, 25, 9, 40)));
        call(200, "/api/metro/clearing/seal", new SealRequest("s7",
                java.time.LocalDate.of(2026, 9, 25)));

        // 同键同参重放申请
        RefundApplyRequest apply = new RefundApplyRequest("ra7", "RFD7", "T7", 100L,
                LocalDateTime.of(2026, 9, 26, 9, 0));
        JsonNode first = call(200, "/api/metro/refunds", apply);
        assertTrue(!first.get("replayed").asBoolean());
        JsonNode replay = call(200, "/api/metro/refunds", apply);
        assertTrue(replay.get("replayed").asBoolean());

        // 同键异参（金额不同）-> 409，不占键之外不新增退款单
        JsonNode conflict = call(409, "/api/metro/refunds",
                new RefundApplyRequest("ra7", "RFD7", "T7", 101L,
                        LocalDateTime.of(2026, 9, 26, 9, 0)));
        assertEquals("IDEMPOTENCY_CONFLICT", conflict.get("code").asText());

        // 确认：同键、集合元素顺序不同仍视为同参（集合无序），重放成功
        call(200, "/api/metro/refunds/RFD7/confirm",
                new RefundConfirmRequest("rc7", "RFD7", 1,
                        java.util.Set.of("u1", "u2"), LocalDateTime.of(2026, 9, 26, 9, 1)));
        JsonNode confirmedReplay = callRaw(200, "/api/metro/refunds/RFD7/confirm",
                "{\"requestId\":\"rc7\",\"refundNo\":\"RFD7\",\"expectedVersion\":1,"
                        + "\"reviewers\":[\"u2\",\"u1\"],\"confirmTime\":\"2026-09-26T09:01:00\"}");
        assertTrue(confirmedReplay.get("replayed").asBoolean());

        // 同键、版本不同 -> 409
        JsonNode versionConflict = call(409, "/api/metro/refunds/RFD7/confirm",
                new RefundConfirmRequest("rc7", "RFD7", 2,
                        java.util.Set.of("u1", "u2"), LocalDateTime.of(2026, 9, 26, 9, 1)));
        assertEquals("IDEMPOTENCY_CONFLICT", versionConflict.get("code").asText());

        // 只落了一笔退款单
        assertEquals(1L, jdbcTemplate.queryForObject(
                "SELECT COUNT(*) FROM refund_order WHERE refund_no = 'RFD7'", Long.class));
    }

    @Test
    void failedRequestDoesNotOccupyIdempotencyKey() throws Exception {
        call(200, "/api/metro/entry", new EntryRequest("e8", "T8", "CARD8", "A",
                LocalDateTime.of(2026, 9, 25, 9, 0)));
