                LocalDateTime.of(2026, 9, 25, 9, 40)));
        call(200, "/api/metro/clearing/seal", new SealRequest("s8",
                java.time.LocalDate.of(2026, 9, 25)));

        // 同键先失败（超退），再以同键发合法请求：失败不占键
        JsonNode failed = call(422, "/api/metro/refunds",
                new RefundApplyRequest("ra8", "RFD8", "T8", 600L,
                        LocalDateTime.of(2026, 9, 26, 9, 0)));
        assertEquals("REFUND_EXCEEDS_FARE", failed.get("code").asText());
        JsonNode success = call(200, "/api/metro/refunds",
                new RefundApplyRequest("ra8", "RFD8", "T8", 100L,
                        LocalDateTime.of(2026, 9, 26, 9, 0)));
        assertEquals("PENDING", success.get("status").asText());
        assertTrue(!success.get("replayed").asBoolean());
    }

    @Test
    void structuredFingerprintDistinguishesDelimiterBearingReviewerNames() throws Exception {
        call(200, "/api/metro/entry", new EntryRequest("e9", "T9", "CARD9", "A",
                LocalDateTime.of(2026, 9, 25, 9, 0)));
        call(200, "/api/metro/exit", new ExitRequest("x9", "T9", "F",
