                LocalDateTime.of(2026, 9, 26, 9, 0)));

        // 含分隔符的合法文本可作为复核人，正常确认
        JsonNode ok = call(200, "/api/metro/refunds/RFD9/confirm",
                new RefundConfirmRequest("rc9", "RFD9", 1,
                        java.util.Set.of("a|b", "c|d"), LocalDateTime.of(2026, 9, 26, 9, 1)));
        assertEquals("a|b", ok.get("reviewerOne").asText());
        assertEquals("c|d", ok.get("reviewerTwo").asText());

        // 同键换一名含分隔符复核人 -> 结构化指纹不同，409
        JsonNode conflict = call(409, "/api/metro/refunds/RFD9/confirm",
                new RefundConfirmRequest("rc9", "RFD9", 1,
                        java.util.Set.of("a|b", "c|e"), LocalDateTime.of(2026, 9, 26, 9, 1)));
        assertEquals("IDEMPOTENCY_CONFLICT", conflict.get("code").asText());
    }

    @Test
    void closingCardDoesNotAffectSuccessfulRefundReplay() throws Exception {
        call(200, "/api/metro/entry", new EntryRequest("e10", "T10", "CARD10", "A",
                LocalDateTime.of(2026, 9, 25, 9, 0)));
        call(200, "/api/metro/exit", new ExitRequest("x10", "T10", "F",
                LocalDateTime.of(2026, 9, 25, 9, 40)));
        call(200, "/api/metro/clearing/seal", new SealRequest("s10",
                java.time.LocalDate.of(2026, 9, 25)));
        call(200, "/api/metro/refunds", new RefundApplyRequest("ra10", "RFD10", "T10", 100L,
                LocalDateTime.of(2026, 9, 26, 9, 0)));
        call(200, "/api/metro/refunds/RFD10/confirm",
                new RefundConfirmRequest("rc10", "RFD10", 1,
                        java.util.Set.of("u1", "u2"), LocalDateTime.of(2026, 9, 26, 9, 1)));

        // 关闭票卡
        JsonNode closed = call(200, "/api/metro/cards/CARD10/close",
                new CardCloseRequest("rd10", "CARD10", 1,
                        LocalDateTime.of(2026, 9, 26, 12, 0)));
        assertEquals("CLOSED", closed.get("status").asText());
        assertEquals(2, closed.get("version").asInt());

        // 关卡后已成功退款的同键历史重放仍成功
        JsonNode replay = call(200, "/api/metro/refunds/RFD10/confirm",
                new RefundConfirmRequest("rc10", "RFD10", 1,
                        java.util.Set.of("u1", "u2"), LocalDateTime.of(2026, 9, 26, 9, 1)));
        assertTrue(replay.get("replayed").asBoolean());
        assertEquals("CONFIRMED", replay.get("status").asText());

        // 版本错误的关卡请求 -> 409
        JsonNode badVersion = call(409, "/api/metro/cards/CARD10/close",
                new CardCloseRequest("rd10b", "CARD10", 1,
                        LocalDateTime.of(2026, 9, 26, 12, 1)));
        assertEquals("VERSION_CONFLICT", badVersion.get("code").asText());
    }

