    void missingRefundAndBatchReturn404() throws Exception {
        assertEquals("REFUND_NOT_FOUND",
                getJson(404, "/api/metro/refunds/UNKNOWN").get("code").asText());

        JsonNode seal = call(404, "/api/metro/adjustment-batches/AJB999999/seal",
                new AdjustmentSealRequest("rsx", "AJB999999", 1,
