package com.example.starter.metro;

import java.time.LocalDate;
import java.time.LocalDateTime;
import java.util.ArrayList;
import java.util.List;
import java.util.Set;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.TimeUnit;

import com.example.starter.metro.MetroRepository.DetailRow;
import com.example.starter.metro.dto.AdjustmentIncludeRequest;
import com.example.starter.metro.dto.AdjustmentIncludeResponse;
import com.example.starter.metro.dto.EntryRequest;
import com.example.starter.metro.dto.ExitRequest;
import com.example.starter.metro.dto.RefundApplyRequest;
import com.example.starter.metro.dto.RefundConfirmRequest;
import com.example.starter.metro.dto.RefundConfirmResponse;
import com.example.starter.metro.dto.SealRequest;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.JdbcTemplate;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * 退款冲正并发与幂等边界测试（H2 内存库，MySQL 兼容模式）：
 * 真实多线程验证并发双人确认不超退、同键并发只生效一次、并发纳入共享唯一开放批次。
 */
@SpringBootTest
class RefundConcurrencyTest {

    @Autowired
    private MetroService metroService;

    @Autowired
    private RefundService refundService;

    @Autowired
    private MetroRepository repository;

    @Autowired
    private JdbcTemplate jdbcTemplate;

    private ExecutorService executor;

    @BeforeEach
    void setUp() {
        jdbcTemplate.update("DELETE FROM adjustment_detail");
        jdbcTemplate.update("DELETE FROM refund_order");
        jdbcTemplate.update("DELETE FROM adjustment_batch");
        jdbcTemplate.update("DELETE FROM clearing_detail");
        jdbcTemplate.update("DELETE FROM clearing_discrepancy");
        jdbcTemplate.update("DELETE FROM metro_transaction");
        jdbcTemplate.update("DELETE FROM clearing_batch");
        jdbcTemplate.update("DELETE FROM metro_card");
        jdbcTemplate.update("DELETE FROM idempotency_record");
        executor = Executors.newFixedThreadPool(8);
    }

    @AfterEach
    void tearDown() throws InterruptedException {
        executor.shutdown();
        assertTrue(executor.awaitTermination(10, TimeUnit.SECONDS));
    }

    private void seedSealedTrip(String txnNo, String cardId) {
        metroService.entry(new EntryRequest("e-" + txnNo, txnNo, cardId, "A",
                LocalDateTime.of(2026, 9, 25, 9, 0)));
        metroService.exit(new ExitRequest("x-" + txnNo, txnNo, "F",
                LocalDateTime.of(2026, 9, 25, 9, 40)));
        metroService.seal(new SealRequest("s-" + txnNo, LocalDate.of(2026, 9, 25)));
    }

    private <T> List<T> runConcurrently(int threads, java.util.function.IntFunction<T> task)
            throws Exception {
        CountDownLatch ready = new CountDownLatch(threads);
        CountDownLatch start = new CountDownLatch(1);
        List<Future<T>> futures = new ArrayList<>();
        for (int i = 0; i < threads; i++) {
            int index = i;
            futures.add(executor.submit(() -> {
                ready.countDown();
                assertTrue(start.await(5, TimeUnit.SECONDS));
                return task.apply(index);
            }));
        }
        assertTrue(ready.await(5, TimeUnit.SECONDS));
        start.countDown();
        List<T> results = new ArrayList<>();
        for (Future<T> future : futures) {
            results.add(future.get(20, TimeUnit.SECONDS));
        }
        return results;
    }

    @Test
    void concurrentConfirmsOnSameTripNeverOverRefund() throws Exception {
        seedSealedTrip("TC1", "CARD-C1");
        int refunds = 8;
        long each = 100L;
        for (int i = 0; i < refunds; i++) {
            refundService.apply(new RefundApplyRequest("ra-c1-" + i, "RFD-C1-" + i, "TC1", each,
                    LocalDateTime.of(2026, 9, 26, 9, i)));
        }

        List<Object> outcomes = runConcurrently(refunds, i -> {
            try {
                return refundService.confirm(new RefundConfirmRequest("rc-c1-" + i, "RFD-C1-" + i,
                        1, Set.of("rev-a", "rev-b"), LocalDateTime.of(2026, 9, 26, 10, 0)));
            } catch (MetroException ex) {
                return ex;
            }
        });

        long successes = outcomes.stream().filter(o -> o instanceof RefundConfirmResponse).count();
        assertEquals(5L, successes, "原实收 500 分，并发 8 笔 100 分确认恰好成功 5 笔");
        long rejected = outcomes.stream()
                .filter(o -> o instanceof MetroException)
                .map(o -> (MetroException) o)
                .filter(ex -> ex.getStatus() == HttpStatus.UNPROCESSABLE_ENTITY
                        && "REFUND_EXCEEDS_FARE".equals(ex.getCode()))
                .count();
        assertEquals(3L, rejected, "超额的 3 笔必须被业务拒绝");

        // 负向调整合计恰为 -500，各线路累计不超原份额
        Long total = jdbcTemplate.queryForObject(
                "SELECT COALESCE(SUM(amount_cents),0) FROM adjustment_detail WHERE txn_no = 'TC1'",
                Long.class);
        assertEquals(-500L, total);
        for (DetailRow original : repository.findSettlementDetailsByTxn("TC1")) {
            Long lineRefund = jdbcTemplate.queryForObject(
                    "SELECT COALESCE(-SUM(amount_cents),0) FROM adjustment_detail"
                            + " WHERE txn_no = 'TC1' AND line_code = ?",
                    Long.class, original.lineCode());
            assertTrue(lineRefund <= original.amountCents(),
                    "线路 " + original.lineCode() + " 退款 " + lineRefund
                            + " 超过原份额 " + original.amountCents());
        }
        // 行程可退余额恰为 0
        assertEquals(0L, refundService.lineBalances("TC1").remainingCents());
        // 原封账合计不变
        assertEquals(500L, repository.findBatchByDate(LocalDate.of(2026, 9, 25)).orElseThrow()
                .totalCents());
    }

    @Test
    void concurrentSameKeyConfirmAppliesExactlyOnce() throws Exception {
        seedSealedTrip("TC2", "CARD-C2");
        refundService.apply(new RefundApplyRequest("ra-c2", "RFD-C2", "TC2", 100L,
                LocalDateTime.of(2026, 9, 26, 9, 0)));
        RefundConfirmRequest request = new RefundConfirmRequest("rc-c2", "RFD-C2", 1,
                Set.of("rev-a", "rev-b"), LocalDateTime.of(2026, 9, 26, 10, 0));

        List<RefundConfirmResponse> responses = runConcurrently(8, i -> refundService.confirm(request));
        long fresh = responses.stream().filter(r -> !r.replayed()).count();
        assertEquals(1L, fresh, "同键并发确认恰好一笔实际生效");
        for (RefundConfirmResponse response : responses) {
            assertEquals(2, response.version());
            assertEquals("CONFIRMED", response.status());
        }
        Long detailCount = jdbcTemplate.queryForObject(
                "SELECT COUNT(*) FROM adjustment_detail WHERE refund_no = 'RFD-C2'", Long.class);
        assertEquals(2L, detailCount, "只生成两条（每线路一条）负向调整明细");
        Long idemCount = jdbcTemplate.queryForObject(
                "SELECT COUNT(*) FROM idempotency_record WHERE scope = 'REFUND_CONFIRM'"
                        + " AND request_id = 'rc-c2'",
                Long.class);
        assertEquals(1L, idemCount);
    }

    @Test
    void concurrentIncludesShareSingleOpenBatchWithoutDoubleCount() throws Exception {
        seedSealedTrip("TC3", "CARD-C3");
        int refunds = 3;
        for (int i = 0; i < refunds; i++) {
            String refundNo = "RFD-C3-" + i;
            refundService.apply(new RefundApplyRequest("ra-c3-" + i, refundNo, "TC3", 100L,
                    LocalDateTime.of(2026, 9, 26, 9, i)));
            refundService.confirm(new RefundConfirmRequest("rc-c3-" + i, refundNo, 1,
                    Set.of("rev-a", "rev-b"), LocalDateTime.of(2026, 9, 26, 10, i)));
        }

        List<AdjustmentIncludeResponse> responses = runConcurrently(refunds, i ->
                refundService.include(new AdjustmentIncludeRequest("ri-c3-" + i, "RFD-C3-" + i, 2,
                        LocalDateTime.of(2026, 9, 26, 11, 0))));

        long batchCount = responses.stream().map(AdjustmentIncludeResponse::batchNo).distinct().count();
        assertEquals(1L, batchCount, "并发纳入共享同一个开放调账批次");
        for (AdjustmentIncludeResponse response : responses) {
            assertEquals("OPEN", response.batchStatus());
            assertTrue(response.firstInclude());
        }
        long openBatches = jdbcTemplate.queryForObject(
                "SELECT COUNT(*) FROM adjustment_batch WHERE status = 'OPEN'", Long.class);
        assertEquals(1L, openBatches);
        Long total = jdbcTemplate.queryForObject(
                "SELECT COALESCE(SUM(total_cents),0) FROM adjustment_batch WHERE status = 'OPEN'",
                Long.class);
        assertEquals(-300L, total, "三笔各 100 分的负向合计不重复计额");
        Long orderCount = jdbcTemplate.queryForObject(
                "SELECT order_count FROM adjustment_batch WHERE status = 'OPEN'", Long.class);
        assertEquals(3L, orderCount);
    }
}

