/** 进闸时确保票卡已开立（同一票卡并发/重复进闸不重复开立、不报错）。 */
public void ensureCard(String cardId) {
    LocalDateTime now = LocalDateTime.now();
    try {
        jdbcTemplate.update(
                "INSERT INTO metro_card (card_id, status, version, created_at, updated_at)"
                + " SELECT ?, 'ACTIVE', 1, ?, ? WHERE NOT EXISTS ("
                + " SELECT 1 FROM metro_card WHERE card_id = ?)",
                cardId, Timestamp.valueOf(now), Timestamp.valueOf(now), cardId);
    } catch (DuplicateKeyException ex) {
        // 并发进闸同一票卡：另一方已开立，本事务无需建卡
    }
}

